// The contract your application speaks. Nothing below is vendor-shaped.
public interface ILlmProvider
{
    Task<CompletionResult> CompleteAsync(PromptRequest request, CancellationToken ct = default);

    IAsyncEnumerable<string> StreamAsync(PromptRequest request, CancellationToken ct = default);
}

public sealed record PromptRequest(
    string SystemPrompt,
    IReadOnlyList<ChatTurn> History,
    string UserMessage,
    int MaxOutputTokens = 1024,
    double Temperature = 0.2,
    string? JsonSchema = null);          // set when the caller needs structured output

public sealed record ChatTurn(ChatRole Role, string Content);
public enum ChatRole { User, Assistant }

public sealed record CompletionResult(
    string Text,
    TokenUsage Usage,
    FinishReason Finish);

// Returned from every call, whether or not anything reads it yet. Adding this
// after the feature is live means backfilling every call site.
public sealed record TokenUsage(int InputTokens, int OutputTokens)
{
    public int Total => InputTokens + OutputTokens;
}

/// <summary>Why generation stopped. <see cref="Length"/> means the answer is
/// cut off, which is the usual reason structured output fails to parse.</summary>
public enum FinishReason { Stop, Length, ContentFilter, ToolCall }


public sealed class AzureOpenAiProvider(
    HttpClient http,
    IOptions<LlmOptions> options,
    ILogger<AzureOpenAiProvider> log) : ILlmProvider
{
    public async Task<CompletionResult> CompleteAsync(PromptRequest request, CancellationToken ct = default)
    {
        var result = await SendWithRetryAsync(request, ct);

        if (result.Finish == FinishReason.Length)
        {
            // Not an exception — a real outcome the caller must be able to see.
            // Swallowing it is how a truncated JSON object reaches a parser and
            // surfaces as an unrelated deserialisation error three layers up.
            log.LogWarning("completion truncated at {Tokens} output tokens", result.Usage.OutputTokens);
        }

        return result;
    }

    private async Task<CompletionResult> SendWithRetryAsync(PromptRequest request, CancellationToken ct)
    {
        for (var attempt = 1; ; attempt++)
        {
            using var response = await http.PostAsJsonAsync(
                options.Value.CompletionsPath, ToProviderPayload(request), ct);

            // A 429 is an operating condition for a model API, not a fault.
            if (response.StatusCode is HttpStatusCode.TooManyRequests && attempt < options.Value.MaxAttempts)
            {
                var wait = response.Headers.RetryAfter?.Delta
                           ?? TimeSpan.FromSeconds(Math.Min(Math.Pow(2, attempt), 30));
                await Task.Delay(Jitter(wait), ct);
                continue;
            }

            response.EnsureSuccessStatusCode();
            return ToResult(await response.Content.ReadFromJsonAsync<ProviderResponse>(ct));
        }
    }

    // Without jitter every caller that was rate-limited together retries
    // together and reproduces the limit they were waiting out.
    private static TimeSpan Jitter(TimeSpan wait) =>
        wait * (0.5 + Random.Shared.NextDouble() / 2);
}

[HttpPost("messages/stream")]
public async IAsyncEnumerable<ChatChunk> Stream(
    ChatRequest request,
    [EnumeratorCancellation] CancellationToken ct)
{
    // Kestrel and any compression middleware will otherwise buffer this and
    // deliver it in one block. It is the reason streaming works on a laptop
    // and does not in the deployed environment.
    var feature = HttpContext.Features.Get<IHttpResponseBodyFeature>();
    feature?.DisableBuffering();
    Response.Headers.ContentType = "text/event-stream";
    Response.Headers.CacheControl = "no-cache";
    Response.Headers["X-Accel-Buffering"] = "no";   // nginx

    var builder = new StringBuilder();
    var finished = false;

    try
    {
        await foreach (var token in chat.StreamAsync(request, ct))
        {
            builder.Append(token);
            yield return new ChatChunk(token, Done: false);
        }
        finished = true;
    }
    finally
    {
        // Runs on cancellation too. One write at the end, not one per token —
        // and the partial answer is kept deliberately rather than lost or
        // half-written.
        await conversations.AppendAsync(
            request.ConversationId,
            builder.ToString(),
            complete: finished,
            CancellationToken.None);   // the request token is already cancelled
    }

    yield return new ChatChunk(string.Empty, Done: true);
}

public sealed record ChatChunk(string Token, bool Done, string? Error = null);


// --- the error channel ----------------------------------------------------
// Once the first byte of a 200 is written the status code is fixed. A failure
// after that point has to travel on the stream itself, or the client renders a
// truncated answer as a complete one.
await foreach (var token in provider.StreamAsync(prompt, ct))
{
    ChatChunk chunk;
    try
    {
        chunk = new ChatChunk(token, Done: false);
    }
    catch (Exception ex)
    {
        log.LogError(ex, "stream failed for conversation {Id}", request.ConversationId);
        yield return new ChatChunk(string.Empty, Done: true, Error: "The answer was cut short.");
        yield break;
    }
    yield return chunk;
}

// The type the application works in. The schema sent to the model is derived
// from this, so the two cannot drift apart.
public sealed record ExtractedInvoice(
    string? InvoiceNumber,
    DateOnly? IssuedOn,
    decimal? NetAmount,
    string? CurrencyCode,
    InvoiceCategory? Category,
    // Absence has to be representable. A schema that demands every field is a
    // schema the model will satisfy by inventing values.
    IReadOnlyList<string> FieldsNotFound);

public enum InvoiceCategory { Services, Hardware, Software, Travel, Other }


public sealed class InvoiceExtractor(ILlmProvider llm, ILogger<InvoiceExtractor> log)
{
    private const string System = """
        Extract invoice fields from the supplied document text.

        Return null for any field the document does not state, and name that
        field in fieldsNotFound. Do not infer a value from context, and do not
        guess a currency from the country. Leaving a field null is correct and
        expected.
        """;

    public async Task<Result<ExtractedInvoice>> ExtractAsync(string documentText, CancellationToken ct)
    {
        for (var attempt = 1; attempt <= 2; attempt++)
        {
            var completion = await llm.CompleteAsync(new PromptRequest(
                System, [], documentText,
                MaxOutputTokens: 800,
                JsonSchema: SchemaFor<ExtractedInvoice>()), ct);

            // Before parsing: a truncated response fails deserialisation with an
            // error that says nothing about the real cause.
            if (completion.Finish == FinishReason.Length)
                return Result.Fail<ExtractedInvoice>(
                    "The document was too long to extract in one pass; split it and retry.");

            ExtractedInvoice? parsed;
            try
            {
                parsed = JsonSerializer.Deserialize<ExtractedInvoice>(completion.Text, JsonOptions);
            }
            catch (JsonException ex) when (attempt == 1)
            {
                // One retry, with the error fed back. Repeated retries burn
                // tokens on a prompt that is not working.
                log.LogWarning(ex, "malformed extraction, retrying once");
                continue;
            }
            catch (JsonException ex)
            {
                log.LogError(ex, "extraction unparseable after retry");
                return Result.Fail<ExtractedInvoice>("Could not read the document.");
            }

            if (parsed is null) continue;

            // Shape is not correctness. Both of these parse perfectly.
            if (parsed.NetAmount is < 0)
                return Result.Fail<ExtractedInvoice>("Extracted a negative net amount; rejected.");

            if (parsed.CurrencyCode is { } code && !SupportedCurrencies.Contains(code))
                return Result.Fail<ExtractedInvoice>($"Unrecognised currency '{code}'.");

            return Result.Ok(parsed);
        }

        return Result.Fail<ExtractedInvoice>("Could not read the document.");
    }
}

// prompts/renewal-assistant.v4.md, in the repository and code-reviewed.
//
// ---
// id: renewal-assistant
// version: 4
// changed: 2026-09-20  Added the refusal clause after eval case 17 regressed.
// ---
// You answer questions about renewal contracts...

public sealed record PromptTemplate(string Id, int Version, string Body);

public interface IPromptStore
{
    /// <summary>The pinned version for this environment — never "latest".
    /// A prompt that changes under a running deployment is a behaviour change
    /// nobody reviewed.</summary>
    PromptTemplate Get(string id);
}

public sealed class RenewalAssistant(ILlmProvider llm, IPromptStore prompts, IAnswerLog answers)
{
    public async Task<Answer> AskAsync(string question, IReadOnlyList<Clause> clauses,
                                       Guid conversationId, CancellationToken ct)
    {
        var prompt = prompts.Get("renewal-assistant");

        // Instructions and data are separate turns. Retrieved text never enters
        // the system prompt, and it arrives inside a delimited block that the
        // instructions describe as data.
        var context = string.Join("\n\n", clauses.Select(c => $"[{c.Id}] {c.Text}"));
        var completion = await llm.CompleteAsync(new PromptRequest(
            SystemPrompt: prompt.Body,
            History: [],
            UserMessage: $"""
                <clauses>
                {context}
                </clauses>

                Question: {question}
                """), ct);

        // The prompt version travels with the answer. Six weeks later, "why did
        // it say that?" is a lookup rather than an investigation.
        await answers.RecordAsync(new AnswerRecord(
            conversationId,
            PromptId: prompt.Id,
            PromptVersion: prompt.Version,
            Question: question,
            Text: completion.Text,
            InputTokens: completion.Usage.InputTokens,
            OutputTokens: completion.Usage.OutputTokens), ct);

        return new Answer(completion.Text, prompt.Version);
    }
}

/// <summary>
/// Cost per unit of business work — here, per triaged ticket. A ticket may
/// take several model calls; the business compares the total against the
/// analyst minutes it replaces, so that is the number worth reporting.
/// </summary>
public sealed class WorkUnitCost
{
    private readonly List<(string Purpose, TokenUsage Usage)> _calls = [];

    public void Record(string purpose, TokenUsage usage) => _calls.Add((purpose, usage));

    public decimal CostUsd(ModelPricing pricing) =>
        _calls.Sum(c => c.Usage.InputTokens  / 1_000_000m * pricing.InputPerMillion
                      + c.Usage.OutputTokens / 1_000_000m * pricing.OutputPerMillion);

    /// <summary>Which call dominates. Almost always the one carrying retrieval.</summary>
    public IEnumerable<(string Purpose, decimal Cost)> Breakdown(ModelPricing pricing) =>
        _calls.Select(c => (c.Purpose,
                            c.Usage.InputTokens  / 1_000_000m * pricing.InputPerMillion
                          + c.Usage.OutputTokens / 1_000_000m * pricing.OutputPerMillion))
              .OrderByDescending(x => x.Item2);
}

// Typical output for one triaged ticket:
//   classify (no retrieval)     in=   540 out=  40   $0.0022
//   answer   (8 passages)       in=  9120 out= 310   $0.0320
//   -> $0.034/ticket; at 12,000 tickets/month = $410/month
//
// The lever is visible: the retrieval call is 94% of it. Cutting 8 passages to
// 4 was tested against the eval set — $410 -> $230/month, accuracy unchanged.


// --- separate allocations, so a bulk import cannot starve the chat ---------
builder.Services.AddHttpClient<ILlmProvider, AzureOpenAiProvider>("interactive")
    .AddResilienceHandler("interactive", b => b
        .AddConcurrencyLimiter(permitLimit: 20)
        .AddTimeout(TimeSpan.FromSeconds(30)));

builder.Services.AddHttpClient<ILlmProvider, AzureOpenAiProvider>("batch")
    .AddResilienceHandler("batch", b => b
        .AddConcurrencyLimiter(permitLimit: 4)        // deliberately smaller
        .AddTimeout(TimeSpan.FromMinutes(5)));

// A runaway loop against a model is expensive in a way a runaway loop against
// a database is not. Cap it, and alarm well below the cap.
if (await spend.ThisHourAsync(ct) > options.Value.HourlyBudgetUsd)
{
    log.LogCritical("hourly model spend budget exceeded; interactive calls suspended");
    throw new BudgetExceededException();
}

public sealed record Chunk(
    string Id,
    string DocumentId,
    int DocumentVersion,          // superseded passages must stop being retrievable
    string HeadingPath,           // "Acme MSA 2026 > Section 7 > Termination"
    string Text,
    IReadOnlyList<string> SecurityLabels,
    DateOnly? EffectiveFrom,
    DateOnly? EffectiveTo)
{
    /// <summary>What actually gets embedded and shown. A passage reading
    /// "This shall not exceed 30 days." is useless without its heading path,
    /// and adding it usually beats any prompt change.</summary>
    public string Contextualised => $"{HeadingPath}\n\n{Text}";
}

public sealed class StructuralChunker(ChunkOptions options)
{
    public IEnumerable<Chunk> Chunk(ParsedDocument doc)
    {
        // Structure first. Fixed-size splitting cuts clauses in half and
        // separates a numbered term from its number.
        foreach (var section in doc.Sections)
        {
            var path = $"{doc.Title} > {string.Join(" > ", section.HeadingTrail)}";

            // A table flattened into prose is usually unusable. Index it whole,
            // with its header row, and only split it if it is enormous.
            if (section.IsTable)
            {
                yield return New(doc, path, section.Text, section.Ordinal);
                continue;
            }

            if (EstimateTokens(section.Text) <= options.MaxTokens)
            {
                yield return New(doc, path, section.Text, section.Ordinal);
                continue;
            }

            // Only now fall back to size, and split on sentence boundaries so a
            // chunk never ends mid-thought.
            var ordinal = 0;
            foreach (var window in SplitOnSentences(section.Text, options.MaxTokens, options.OverlapRatio))
                yield return New(doc, path, window, section.Ordinal * 1000 + ordinal++);
        }
    }

    private Chunk New(ParsedDocument doc, string path, string text, int ordinal) => new(
        Id: $"{doc.Id}:v{doc.Version}:{ordinal}",
        DocumentId: doc.Id,
        DocumentVersion: doc.Version,
        HeadingPath: path,
        Text: text,
        // Captured at index time. You cannot filter on what you did not store,
        // and adding it later means re-indexing the entire corpus.
        SecurityLabels: doc.SecurityLabels,
        EffectiveFrom: doc.EffectiveFrom,
        EffectiveTo: doc.EffectiveTo);
}

public sealed record ChunkOptions(int MaxTokens = 600, double OverlapRatio = 0.12);

public sealed class HybridRetriever(
    ISearchIndex index, IEmbeddingModel embedder, IReranker reranker)
{
    public async Task<IReadOnlyList<Chunk>> RetrieveAsync(
        string question, RetrievalFilter filter, int take, CancellationToken ct)
    {
        var vector = await embedder.EmbedAsync(question, ct);

        // Both arms, in parallel. Vector finds "termination for convenience"
        // from "cancelling early"; keyword finds contract reference MSA-4471,
        // which vector search is reliably bad at.
        var semanticTask = index.VectorSearchAsync(vector, filter, take: 50, ct);
        var keywordTask  = index.KeywordSearchAsync(question, filter, take: 50, ct);
        await Task.WhenAll(semanticTask, keywordTask);

        // Reciprocal rank fusion: no score normalisation needed between two
        // scales that are not comparable.
        var fused = ReciprocalRankFusion(semanticTask.Result, keywordTask.Result);

        // Retrieve broadly, rerank, keep few. The right passage is often in the
        // first 50 and not the first 5, and this is what moves it.
        var reranked = await reranker.RankAsync(question, fused.Take(50).ToList(), ct);
        return reranked.Take(take).ToList();
    }

    private static IEnumerable<Chunk> ReciprocalRankFusion(
        IReadOnlyList<Chunk> a, IReadOnlyList<Chunk> b, int k = 60)
    {
        var scores = new Dictionary<string, (Chunk Chunk, double Score)>();
        foreach (var list in new[] { a, b })
            for (var rank = 0; rank < list.Count; rank++)
            {
                var chunk = list[rank];
                var add = 1.0 / (k + rank + 1);
                scores[chunk.Id] = scores.TryGetValue(chunk.Id, out var existing)
                    ? (chunk, existing.Score + add)
                    : (chunk, add);
            }

        return scores.Values.OrderByDescending(x => x.Score).Select(x => x.Chunk);
    }
}

// Embeddings are comparable only within one model. Record which produced each
// vector: changing models means re-embedding the corpus, with no partial path.
public sealed record StoredVector(string ChunkId, float[] Values, string EmbeddingModelId);

public sealed class SecureRetriever(ISearchIndex index, IUserDirectory directory,
                                    IRetrievalAudit audit)
{
    public async Task<IReadOnlyList<Chunk>> RetrieveAsync(
        string question, Guid userId, CancellationToken ct)
    {
        // Resolved NOW, not from a snapshot taken at ingestion. Someone removed
        // from a group this morning must not retrieve its documents this
        // afternoon.
        var groups = await directory.GetGroupsAsync(userId, ct);

        var filter = new RetrievalFilter
        {
            // Applied INSIDE the index query. Post-filtering leaks two ways: the
            // result count discloses that something exists, and in the naive
            // implementation the passage already reached the prompt, where the
            // model can summarise what it was shown.
            AnySecurityLabel = groups,
            CurrentVersionOnly = true,
            EffectiveOn = DateOnly.FromDateTime(DateTime.UtcNow),
        };

        var chunks = await index.SearchAsync(question, filter, take: 8, ct);

        // Evidence, not reassurance. "Did the assistant ever surface document X
        // to person Y" has to be answerable with a query.
        await audit.RecordAsync(userId, question, chunks.Select(c => c.Id).ToList(), ct);

        return chunks;
    }
}

