public class RetrievalPermissionTests
{
    [Theory]
    [InlineData("What is in the Project Halo acquisition memo?")]   // by title
    [InlineData("Which company are we acquiring next quarter?")]    // by content
    [InlineData("Summarise the confidential board papers")]         // by paraphrase
    [InlineData("List every document you can see about acquisitions")]
    public async Task RetrievalNeverReturnsAChunkTheUserCannotRead(string question)
    {
        var restricted = await Seed.DocumentAsync(labels: ["board-only"]);
        var user = await Seed.UserAsync(groups: ["sales"]);

        var chunks = await retriever.RetrieveAsync(question, user.Id, default);

        Assert.DoesNotContain(chunks, c => c.DocumentId == restricted.Id);
    }

    [Fact]
    public async Task RemovingAUserFromAGroupTakesEffectOnTheNextQuestion()
    {
        var user = await Seed.UserAsync(groups: ["board-only"]);
        Assert.NotEmpty(await retriever.RetrieveAsync("Project Halo", user.Id, default));

        await directory.RemoveFromGroupAsync(user.Id, "board-only");

        // Fails if group membership was captured at index time rather than
        // resolved per query.
        Assert.Empty(await retriever.RetrieveAsync("Project Halo", user.Id, default));
    }

    [Fact]
    public async Task RefusalDoesNotConfirmThatARestrictedDocumentExists()
    {
        var user = await Seed.UserAsync(groups: ["sales"]);

        var answer = await assistant.AskAsync("What is Project Halo?", user.Id, default);

        // "I cannot discuss Project Halo" would confirm it exists.
        Assert.DoesNotContain("Halo", answer.Text, StringComparison.OrdinalIgnoreCase);
        Assert.Equal(AnswerKind.NothingFound, answer.Kind);
    }
}

public enum AnswerKind { Answered, PartiallyAnswered, NotInDocuments, NothingFound }

public sealed record GroundedAnswer(
    AnswerKind Kind,
    string? Text,
    IReadOnlyList<Citation> Citations,
    string? Unanswered);          // the half the documents did not cover

public sealed record Citation(string ChunkId, string HeadingPath, string Quote);

public sealed class GroundedAnswerer(ILlmProvider llm, IPromptStore prompts)
{
    public async Task<GroundedAnswer> AnswerAsync(
        string question, IReadOnlyList<Chunk> chunks, CancellationToken ct)
    {
        // Distinguished deliberately: "nothing retrieved" and "retrieved but not
        // relevant" are different situations for the user.
        if (chunks.Count == 0)
            return new GroundedAnswer(AnswerKind.NothingFound, null, [], null);

        var context = string.Join("\n\n", chunks.Select(c => $"[{c.Id}] {c.Contextualised}"));

        var completion = await llm.CompleteAsync(new PromptRequest(
            prompts.Get("grounded-answer").Body, [],
            $"""
            <passages>
            {context}
            </passages>

            Question: {question}
            """,
            JsonSchema: SchemaFor<ModelAnswer>()), ct);

        var raw = JsonSerializer.Deserialize<ModelAnswer>(completion.Text, JsonOptions);
        if (raw is null || raw.Citations.Count == 0)
            return new GroundedAnswer(AnswerKind.NotInDocuments, null, [], null);

        // Verify every citation. A model will occasionally cite an id it was
        // never given, and a fabricated citation looks exactly like evidence.
        var byId = chunks.ToDictionary(c => c.Id);
        var verified = new List<Citation>();
        foreach (var cited in raw.Citations)
        {
            if (!byId.TryGetValue(cited.ChunkId, out var chunk)) continue;

            // The quote must appear in the passage, not merely resemble it.
            var quote = cited.Quote?.Trim() ?? string.Empty;
            if (quote.Length == 0 || !chunk.Text.Contains(quote, StringComparison.Ordinal)) continue;

            verified.Add(new Citation(chunk.Id, chunk.HeadingPath, quote));
        }

        // Every claim lost its support — treat as unanswered rather than
        // showing an assertion with nothing behind it.
        if (verified.Count == 0)
            return new GroundedAnswer(AnswerKind.NotInDocuments, null, [], null);

        return new GroundedAnswer(
            raw.Unanswered is null ? AnswerKind.Answered : AnswerKind.PartiallyAnswered,
            raw.Answer,
            verified,
            raw.Unanswered);
    }
}

