{
    public async Task<bool> IsEnabledAsync(CancellationToken ct) =>
        // Per tenant and per user. The first incident with an AI feature is
        // usually behaviour someone objects to, and that needs a switch that
        // works in seconds rather than a deployment.
        await features.IsEnabledAsync("renewal-assistant", user.TenantId, ct)
        && !await features.IsSuppressedAsync("renewal-assistant", user.Id, ct);
}

