[HttpPost("answers/{correlationId:guid}/feedback")]
public async Task<IActionResult> Feedback(
    Guid correlationId, FeedbackRequest request, CancellationToken ct)
{
    // One click. This single control is the incident queue, the evaluation-set
    // pipeline and the quality metric, and it costs almost nothing to build.
    await feedback.RecordAsync(correlationId, user.Id, request.Helpful, request.Comment, ct);

    if (!request.Helpful)
        // Straight into the eval candidate pool with its full trace: the
        // retrieved passages, the prompt version and the model version.
        await evalCandidates.EnqueueAsync(correlationId, ct);

    return NoContent();
}

-- The dashboard. Every number here degrades without throwing anything.
SELECT date_trunc('day', occurred_at)                              AS day,
       COUNT(*)                                                    AS answers,
       AVG(CASE WHEN human_accepted THEN 1.0 ELSE 0.0 END)         AS acceptance_rate,
       AVG(CASE WHEN kind = 'NotInDocuments' THEN 1.0 ELSE 0 END)  AS refusal_rate,
       PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY latency_ms)    AS p95_ms,
       PERCENTILE_CONT(0.99) WITHIN GROUP (ORDER BY latency_ms)    AS p99_ms,
       SUM(cost_usd)                                               AS spend
FROM   ai_call_log
WHERE  operation = 'renewal.answer' AND occurred_at > now() - INTERVAL '30 days'
GROUP  BY 1 ORDER BY 1;

